  uint64_t modifiers = ((inst_.abs & 1) ? RJ_ARITH_ALU_ABS_A : 0u) |
                       ((inst_.neg & 1) ? RJ_ARITH_ALU_NEG_A : 0u) |
                       (inst_.clamp ? RJ_ARITH_ALU_CLAMP : 0u);
